/* Shared-device profiles, advances, and dividends; passcodes demonstrate identity flow, not production authentication. */
const loanLabels={pending:'等家长提条件',offered:'等我确认条件',approved:'等家长实际垫付',active:'按计划偿还',paid:'已还清',cancelled:'已撤回',rejected:'这次暂不预支'};
function identityMarkup(){return `<div class="identity-strip"><button class="profile-chip" data-action="profiles"><span class="profile-dot ${state.profileId==='xiaohe'?'lavender':''}">${e(state.child.slice(-1))}</span><span>${view.startsWith('parent')?'正在管理':'当前小镇'} · <b>${e(state.child)}</b></span>${icon('chevron',13)}</button>${view.startsWith('parent')?'<span class="tiny muted">各自记账，家长统一管理</span>':link('我的预支计划','go','data-view="loans"')}</div>${!view.startsWith('parent')&&Engine.debt(state)?`<div class="debt-notice">${icon('book',16)}<span class="grow">还有计划待还 <b>¥${money(Engine.debt(state))}</b>，含未来利息</span>${link('查看月供','go','data-view="loans"')}</div>`:''}`;}
function showProfiles(){openModal(parentUnlocked?'选择要管理的孩子':'谁来使用这个小镇？',`<p>两个孩子共用设备，钱包、委托、持有、愿望和还款记录各自独立。</p><div class="profile-picker mt16">${family.children.map(c=>`<button class="profile-option ${c.profileId===state.profileId?'selected':''}" data-action="${parentUnlocked?'manage-child':'enter-child'}" data-id="${c.profileId}"><span class="profile-dot ${c.profileId==='xiaohe'?'lavender':''}">${e(c.child.slice(-1))}</span><strong>${e(c.child)}</strong><small>${parentUnlocked?'查看并管理':c.profileId===state.profileId?'正在使用':'输入自己的口令进入'}</small>${icon(c.profileId===state.profileId?'check':'lock',17)}</button>`).join('')}</div><p class="tiny muted mt16">这是内存原型，口令只用于演示交接设备的流程。刷新会重置全部家庭记录。</p>`);}
function showAccess(kind,target){const child=family.children.find(c=>c.profileId===target);openModal(kind==='parent'?'请家长来确认身份':`进入${e(child?.child||'孩子')}的小镇`,`<div class="modal-illustration ${kind==='parent'?'warm':'purple'}">${icon('lock',65)}</div><p>${kind==='parent'?'家长可以查看两个孩子的记录，审批预支和兑现报酬。':'输入自己的 4 位口令。进入后只操作这个孩子的独立账本。'}</p><form data-form="access" novalidate><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="target" value="${e(target)}"><div class="field mt16"><label for="access-pin">4 位口令</label><input id="access-pin" name="pin" type="password" inputmode="numeric" maxlength="4" autocomplete="off"></div><details class="tiny muted mt16"><summary>查看原型演示口令</summary><p class="mt8">家长 2580 · ${family.children.map(c=>`${e(c.child)} ${e(c.pin)}`).join(' · ')}</p></details><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">${kind==='parent'?'进入家长空间':'进入我的小镇'}</button></form>`);}
function switchProfile(id,asParent=false){const child=family.children.find(c=>c.profileId===id);if(!child)return;closeModal();state=child;taskFilter='all';projectionContribute=false;projectionYears=10;if(!asParent)parentUnlocked=false;go(asParent?'parent':'home');toast(`现在${asParent?'正在管理':'进入'}${child.child}的独立账本。`);}
function resetFamily(){family=Family.initial();state=family.children[0];parentUnlocked=false;if(typeof Game!=='undefined'){Game.profiles={};Game.pan={x:0,y:0};Game.zoom=1;}}
function familyOverview(){const totalBudget=family.children.reduce((v,c)=>v+c.budget,0),reserved=family.children.reduce((v,c)=>v+Engine.reserved(c)+c.bonusEarned,0);return `<section class="card family-overview mb16"><div class="between"><div><h2>一家人的小镇，各自的成长</h2><p class="small muted mt8">先选孩子，再处理他的委托、预算和预支。每个操作都有归属。</p></div>${pill('共用一台设备','purple')}</div><div class="family-grid mt16">${family.children.map(c=>`<button class="family-member ${c.profileId===state.profileId?'selected':''}" data-action="manage-child" data-id="${c.profileId}"><span class="profile-dot ${c.profileId==='xiaohe'?'lavender':''}">${e(c.child.slice(-1))}</span><strong>${e(c.child)}</strong><small>${c.profileId===state.profileId?'正在管理':'切换管理'}</small><div><span>账户资产 ¥${money(Engine.assets(c))}</span><span>计划待还 ¥${money(Engine.debt(c))}</span></div></button>`).join('')}</div><p class="tiny muted mt16">两份收益预算合计 ¥${money(totalBudget)}，已承担及预留 ¥${money(reserved)}；各自预算分别使用，不挪用另一位孩子的份额。借款本金另行垫付。</p></section>`;}
function debtCard(){return `<section class="card debt-card"><div class="between"><h3>我与未来的小约定</h3>${icon('book',21)}</div><div class="rule-row"><span>账户资产</span><strong>¥${money(Engine.assets(state))}</strong></div><div class="rule-row"><span>计划待还，含未来利息</span><strong class="gold">¥${money(Engine.debt(state))}</strong></div><div class="rule-row"><span>扣除计划待还后的账户净额</span><strong>¥${money(Engine.net(state))}</strong></div>${link('查看预支与还款','go','data-view="loans"')}<p class="tiny muted mt8">预支不算收入；这里仅统计 APP 内账户，不包括已购买物品的价值。</p></section>`;}
function scheduleMarkup(schedule){let remaining=schedule.reduce((v,p)=>v+p.principal,0);return `<div class="schedule-scroll"><table class="repayment-table"><thead><tr><th>还款日</th><th>本金</th><th>利息</th><th>本期合计</th><th>计划余本</th><th>进展</th></tr></thead><tbody>${schedule.map(p=>{remaining-=p.principal;const done=p.paidPrincipal===p.principal&&p.paidInterest+p.waivedInterest===p.interest;return `<tr><td>${p.due}</td><td>${money(p.principal)}</td><td>${money(p.interest)}</td><td><strong>${money(p.principal+p.interest)}</strong></td><td>${money(remaining)}</td><td>${done?(p.waivedInterest?'已结清，利息减免':'已还'):p.due<=state.now?'本期可还':'待到期'}</td></tr>`;}).join('')}</tbody></table></div>`;}
function loanSummary(l){const principal=Engine.loanPrincipal(l),balance=Engine.loanBalance(l);return `<div class="loan-totals"><div><small>预支本金</small><strong>¥${money(l.amount)}</strong></div><div><small>约定年利率</small><strong>${(l.rateBps/100).toFixed(2)}%</strong></div><div><small>${l.status==='active'?'计划待还总额':'计划本息合计'}</small><strong class="gold">¥${money(l.status==='active'?balance:l.schedule.reduce((s,p)=>s+p.principal+p.interest,0))}</strong></div></div>${l.status==='active'?`<p class="tiny muted">其中未还本金 ¥${money(principal)}。计划待还总额含未来利息；提前结清会免除未到期利息。</p>`:''}`;}
function loanCard(l,parent=false){return `<article class="card loan-card"><div class="between"><div><span class="tiny muted">${e(state.child)}的预支计划</span><h3 class="mt8">${e(l.item)}</h3></div>${pill(loanLabels[l.status],l.status==='active'?'gold':'neutral')}</div><div class="loan-card-number">¥${money(l.amount)}<small> · ${l.months} 个月</small></div>${l.schedule.length?`<p class="small muted">年利率 ${(l.rateBps/100).toFixed(2)}% · 等额本金 · 首次 ${l.first}</p>`:'<p class="small muted">等待家长提出利率和月供条件；尚未形成欠款。</p>'}<div class="mt16">${button(parent?'查看并处理':'查看约定与月供','loan-detail',`data-id="${l.id}"`,'secondary full')}</div></article>`;}
function loansPage(){return heading('愿望可以提前，约定要慢慢完成','借来的是需要偿还的钱；劳动报酬与分红仍由你安排。',button('申请一笔预支','new-loan','','secondary small'))+`<div class="two-columns"><section class="stack">${state.loans.length?state.loans.map(l=>loanCard(l)).join(''):`<article class="card empty-loans"><div class="modal-illustration warm">${Art.telescope()}</div><h2>先和家长，把愿望说清楚</h2><p class="muted small mt16">想买什么？还差多少？未来每个月准备从哪里还钱？可以先看月供，再决定是否预支。</p><div class="mt24">${button('写下我的预支计划','new-loan','','primary full')}</div></article>`}</section><aside class="stack">${debtCard()}<section class="tip-card"><h3>从未来安排，而不是凭空多一笔钱</h3><p>家长直接垫付购买，不把预支加入理财钱包。<br><br>可以约定无息或有息。家长提条件、孩子确认，再实际垫付，才开始记欠款。<br><br>到期后由你确认还款，不自动扣劳动报酬或现金分红；逾期只提醒，不加罚息。</p></section></aside></div>`;}
function parentLoansPage(){return heading('先把条件说清，再提前实现愿望','这里只处理当前孩子；切换档案可查看另一位孩子的独立计划。',pill(e(state.child)+'的预支','gold'))+`<div class="two-columns"><section class="stack">${state.loans.length?state.loans.map(l=>loanCard(l,true)).join(''):'<section class="card empty">这个孩子还没有提出预支申请。<div class="mt16">'+button('去孩子端写一份计划','go','data-view="loans"','secondary')+'</div></section>'}</section><aside class="stack">${debtCard()}<section class="tip-card"><h3>每一期，先分清本金和利息</h3><p>采用等额本金：本金按月分摊，利息按当期期初未还本金 × 约定年利率 ÷ 12 计算。尾期补足分摊的分位差。<br><br>孩子确认前不生效；已生效条件固定。还款不占用收益预算，也不从另一位孩子账户扣款。</p></section></aside></div>`;}
function showLoanForm(){openModal('写下我的愿望预支',`<form data-form="loan-request" novalidate><div class="form-grid"><div class="field"><label for="loan-item">想提前买什么？</label><input id="loan-item" name="item" value="${e(state.goalName||'第一架天文望远镜')}" maxlength="30"></div><div class="field"><label for="loan-amount">需要家长垫付多少（元）？</label><input id="loan-amount" name="amount" value="60.00" inputmode="decimal" data-input="loan-preview"></div><div class="form-grid split-fields"><div class="field"><label for="loan-months">分几个月偿还？</label><input id="loan-months" name="months" type="number" min="1" max="12" value="3" data-input="loan-preview"></div><div class="field"><label for="loan-first">首次还款日</label><input id="loan-first" name="first" type="date" value="${Day.month(state.now,1)}" data-input="loan-preview"></div></div></div><div class="confirmation-box">下面先按无息提议。家长可以约定利率，你看完最终月供表再决定是否接受。</div><div id="loan-preview"></div><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">把提议交给家长</button></form>`);updateLoanPreview();}
function updateLoanPreview(){const form=document.querySelector('form[data-form="loan-request"],form[data-form="loan-offer"]');if(!form)return;const amount=Money.parse(form.elements.amount.value),months=Number(form.elements.months.value),first=form.elements.first.value,rate=form.elements.rate?Money.parse(form.elements.rate.value):0;const area=document.getElementById('loan-preview');if(!amount||!Number.isInteger(months)||months<1||months>12||!Day.valid(first)||rate===null||rate>1200){area.innerHTML='<p class="tiny muted">填写有效金额、月份、日期和利率后，可查看每月计划。</p>';return;}const schedule=Engine.schedule(amount,months,first,rate),interest=schedule.reduce((sum,p)=>sum+p.interest,0);area.innerHTML=`<div class="between mt16"><h3>每月还款计划</h3><span class="tiny muted">利息合计 ¥${money(interest)}</span></div>${scheduleMarkup(schedule)}<p class="tiny muted mt8">每月本金等额，利息随本金减少；金额按分四舍五入。计划月劳动留存约 ¥${money(Math.round(state.weeklyPlan*52/12))}，尚未发生，不保证能取得。</p>`;}
function showLoanOffer(id){const l=state.loans.find(l=>l.id===id);if(!l||!parentUnlocked)return;openModal('家长提出预支条件',`<h3>${e(state.child)}想买：${e(l.item)}</h3><form data-form="loan-offer" novalidate><input type="hidden" name="id" value="${id}"><input type="hidden" name="amount" value="${l.amount/100}"><div class="form-grid mt16"><div class="field"><label for="offer-rate">约定年利率（%，0 为无息）</label><input id="offer-rate" name="rate" value="${(l.rateBps/100).toFixed(2)}" inputmode="decimal" data-input="loan-preview"><small>原型范围 0%–12%；按月单利，不滚入本金，不加罚息。</small></div><div class="form-grid split-fields"><div class="field"><label for="offer-months">偿还月数</label><input id="offer-months" name="months" type="number" min="1" max="12" value="${l.months}" data-input="loan-preview"></div><div class="field"><label for="offer-first">首次还款日</label><input id="offer-first" name="first" type="date" value="${l.first>state.now?l.first:Day.month(state.now,1)}" data-input="loan-preview"></div></div></div><div id="loan-preview"></div><div class="confirmation-box">条件交给孩子确认后，再实际垫付购买。已生效计划不会被这里的其他约定改动。</div><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">把条件交给孩子确认</button></form>`);updateLoanPreview();}
function showLoanDetail(id){const l=state.loans.find(l=>l.id===id);if(!l)return;const parent=view.startsWith('parent')&&parentUnlocked;let actions='';if(parent){if(['pending','offered'].includes(l.status))actions=`<div class="dual-buttons">${button('这次暂不预支','loan-reject',`data-id="${id}"`,'ghost')}${button('提出或调整条件','loan-offer',`data-id="${id}"`,'primary')}</div>`;if(l.status==='approved')actions=button('确认已实际垫付购买','loan-fund',`data-id="${id}"`,'primary full');if(l.status==='active')actions='<p class="tiny muted mt16">计划已生效，条件固定。请回孩子端让孩子查看月供并主动确认还款。</p>';}else{if(l.status==='offered')actions=`<form data-form="loan-accept" novalidate><input type="hidden" name="id" value="${id}"><label class="check-row mt16"><input name="agree" type="checkbox"><span>我看过本金、利率和每月还款表，愿意按约偿还。提前结清免未到期利息。</span></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">我接受这份约定</button></form>`;if(['pending','offered','approved'].includes(l.status))actions+=`<div class="mt8">${button('我再想想，撤回申请','loan-cancel',`data-id="${id}"`,'ghost full')}</div>`;if(l.status==='active')actions=`<div class="dual-buttons mt16">${button('提前结清','loan-repay',`data-id="${id}" data-mode="settle"`,'ghost')}${button('偿还本期','loan-repay',`data-id="${id}" data-mode="installment"`,'primary')}</div>`;if(['pending','approved'].includes(l.status))actions+=button('请家长看看','loan-parent','','secondary full');}openModal(e(l.item)+' · 预支约定',`${pill(loanLabels[l.status],'gold')}${l.schedule.length?loanSummary(l)+scheduleMarkup(l.schedule):'<div class="confirmation-box">申请中，家长还没有提出正式条件，尚未形成欠款。</div>'}${l.payments.length?`<div class="mt16"><h3>实际偿还记录</h3>${l.payments.map(p=>`<p class="tiny muted mt8">${p.date} · 已还 ¥${money(p.amount)}${p.waived?` · 减免未到期利息 ¥${money(p.waived)}`:''}</p>`).join('')}</div>`:''}${actions}`);}
function showFundLoan(id){const l=state.loans.find(l=>l.id===id);if(!l)return;openModal('实际垫付后，再确认',`<h3>${e(state.child)} · ${e(l.item)}</h3><div class="receipt-total">¥${money(l.amount)}</div><p>家长直接垫付购买。钱不会进入孩子的理财钱包，不会被当成收入。</p><form data-form="loan-fund" novalidate><input type="hidden" name="id" value="${id}"><label class="check-row mt16"><input type="checkbox" name="delivered"><span>孩子已确认约定，我也已实际垫付购买这件物品。</span></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">确认已垫付，计划生效</button></form>`);}
function showRepayment(id,mode){const l=state.loans.find(l=>l.id===id&&l.status==='active');if(!l)return;const next=l.schedule.find(p=>p.principal>p.paidPrincipal||p.interest>p.paidInterest+p.waivedInterest);const amount=mode==='settle'?Engine.loanPrincipal(l)+l.schedule.filter(p=>p.due<=state.now).reduce((s,p)=>s+p.interest-p.paidInterest-p.waivedInterest,0):next.principal+next.interest;openModal(mode==='settle'?'提前结清，少付未来利息':'按约偿还这一期',`<h3>${e(l.item)}</h3><div class="receipt-total">¥${money(amount)}</div><div class="confirmation-box">${mode==='settle'?`免除未到期利息 ¥${money(Engine.loanBalance(l)-amount)}，只还未还本金和已到期未付利息。`:`本期 ${next.due} 应还本金 ¥${money(next.principal)}，利息 ¥${money(next.interest)}。${next.due>state.now?'还款日尚未到，可以稍后回来或选择提前结清。':''}`}<br>可用零钱 ¥${money(state.wallet)}；确认后从你自己的钱包偿还。</div><form data-form="loan-repay" novalidate><input type="hidden" name="id" value="${id}"><input type="hidden" name="mode" value="${mode}"><label class="check-row"><input type="checkbox" name="agree"><span>我决定用这笔零钱还款，知道还款后可以自由安排的钱会减少。</span></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">确认用零钱偿还</button></form>`);}
function distributionChoices(selected,name='distribution'){return `<div class="distribution-options"><label><input type="radio" name="${name}" value="cash" ${selected==='cash'?'checked':''}><span><strong>现金分红</strong><small>收益进零钱，本金同条件续期</small></span></label><label><input type="radio" name="${name}" value="reinvest" ${selected==='reinvest'?'checked':''}><span><strong>红利再投</strong><small>本金与收益一起同条件续期</small></span></label></div>`;}
function showDistribution(id){const p=state.positions.find(p=>p.id===id&&p.status==='active');if(!p)return;openModal('下一次分红，我来选',`<h3>小镇分红计划 · ${e(state.child)}</h3><form data-form="distribution" novalidate><input type="hidden" name="id" value="${id}">${distributionChoices(p.distribution)}<div class="confirmation-box">只改变这笔计划下一次收益的去向，已结算记录不变。同条件续期需要下一期预算充足；利率变化或预算不足时，本息先回钱包。</div><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">保存我的选择</button></form>`);}
function showDividendLesson(mode='cash'){const reinvest=mode==='reinvest';openModal('基金分红，不是额外多一笔收益',`<p>虚构教学情景：100 份 × 分红前净值 1.03 元 = 103 元；本次每份分红 0.03 元，除息后净值为 1.00 元。这里不动用劳动本金。</p><div class="chip-tabs mt16"><button class="chip ${!reinvest?'active':''}" data-action="dividend-lesson" data-mode="cash">现金分红</button><button class="chip ${reinvest?'active':''}" data-action="dividend-lesson" data-mode="reinvest">红利再投</button></div><div class="dividend-equation">${reinvest?'103 份 × 1.00 元':'100 份 × 1.00 元 + 3 元现金'}<strong>总额都是 103.00 元</strong></div><div class="confirmation-box">${reinvest?'3 元红利按除息净值再投，得到 3 份新份额，之后的新涨跌会影响 103 份。':'3 元现金离开基金；剩余 100 份的未来涨跌继续影响基金资产。'}<br>分红只是资产分配，不能再把分红重复加到分红前的 103 元上。实际净值、再投确认日、费用和分红条件以产品规则为准。</div>${button('返回我的理财小屋','go-close','data-view="market"','secondary full')}`);}
document.addEventListener('click',event=>{const t=event.target.closest('[data-action]');if(!t||t.disabled)return;const action=t.dataset.action,id=t.dataset.id;const own=['profiles','manage-child','enter-child','loan-detail','new-loan','loan-offer','loan-reject','loan-cancel','loan-parent','loan-fund','loan-repay','distribution','dividend-lesson','demo-payday'];if(!own.includes(action))return;event.preventDefault();
 if(['manage-child','loan-offer','loan-reject','loan-fund'].includes(action)&&!parentUnlocked)return showAccess('parent','parent-loans');
 if(action==='profiles')return showProfiles();if(action==='manage-child')return switchProfile(id,true);if(action==='enter-child')return id===state.profileId?closeModal():showAccess('child',id);
 if(action==='new-loan')return showLoanForm();if(action==='loan-detail')return showLoanDetail(id);if(action==='loan-offer')return showLoanOffer(id);if(action==='loan-fund')return showFundLoan(id);if(action==='loan-parent'){closeModal();return go('parent-loans');}
 if(action==='loan-cancel'||action==='loan-reject'){const r=action==='loan-cancel'?Engine.cancelLoan(state,id):Engine.rejectLoan(state,id);closeModal();render();return toast(r.message);}
 if(action==='loan-repay')return showRepayment(id,t.dataset.mode);if(action==='distribution')return showDistribution(id);if(action==='dividend-lesson')return showDividendLesson(t.dataset.mode);
 if(action==='demo-payday'){const dues=state.loans.filter(l=>l.status==='active').flatMap(l=>l.schedule.filter(p=>p.principal>p.paidPrincipal||p.interest>p.paidInterest+p.waivedInterest).map(p=>p.due)).sort();return dues.length?advanceDemo(Math.max(0,Day.difference(state.now,dues[0]))):toast('先让一份预支计划生效，再演示还款日。');}
});
document.addEventListener('input',event=>{if(event.target.dataset.input==='loan-preview')updateLoanPreview();});
document.addEventListener('submit',event=>{const form=event.target,type=form.dataset.form;const own=['access','loan-request','loan-offer','loan-accept','loan-fund','loan-repay','distribution'];if(!own.includes(type))return;event.preventDefault();const d=new FormData(form),error=m=>form.querySelector('.form-error').textContent=m;let r;
 if(type==='access'){const kind=d.get('kind'),target=d.get('target'),child=family.children.find(c=>c.profileId===target),expected=kind==='parent'?family.parentPin:child?.pin;if(d.get('pin')!==expected)return error('口令不对，请再试一次。');closeModal();if(kind==='parent'){parentUnlocked=true;go(target);}else switchProfile(target);return;}
 if(['loan-offer','loan-fund'].includes(type)&&!parentUnlocked)return error('请先进入家长空间。');
 if(type==='loan-request')r=Engine.loanRequest(state,d.get('item'),Money.parse(d.get('amount')),Number(d.get('months')),d.get('first'));
 if(type==='loan-offer')r=Engine.offerLoan(state,d.get('id'),Number(d.get('months')),d.get('first'),Money.parse(d.get('rate')));
 if(type==='loan-accept'){if(!d.has('agree'))return error('看清每月还款表，再确认接受。');r=Engine.acceptLoan(state,d.get('id'));}
 if(type==='loan-fund'){if(!d.has('delivered'))return error('请先实际垫付购买，再勾选确认。');r=Engine.fundLoan(state,d.get('id'));}
 if(type==='loan-repay'){if(!d.has('agree'))return error('确认愿意用自己的零钱偿还后，再勾选。');r=Engine.repayment(state,d.get('id'),d.get('mode'));}
 if(type==='distribution')r=Engine.distributionMode(state,d.get('id'),d.get('distribution'));
 if(!r.ok)return error(r.message);closeModal();if(type==='loan-request')go('loans');else render();toast(r.message);
});
